document.documentElement.classList.add("js");

const PHOTOS = [
  {src:"data:image/jpeg;base64,", title:"Above the cloud line", cat:"Landscape", place:"Himalayas", exif:"ƒ/8 · 1/320s · ISO 100 · 24mm", ar:"4/3"},
  {src:"data:image/jpeg;base64,", title:"Old town, after rain", cat:"Street", place:"Europe", exif:"ƒ/2.8 · 1/125s · ISO 400 · 35mm", ar:"3/5"},
  {src:"data:image/jpeg;base64,", title:"Waiting for the sun", cat:"Portrait", place:"Goa", exif:"ƒ/2 · 1/500s · ISO 100 · 50mm", ar:"2/1"},
  {src:"data:image/jpeg;base64,", title:"New growth", cat:"Nature", place:"Coorg", exif:"ƒ/2.8 · 1/200s · ISO 200 · 100mm", ar:"4/3"},
  {src:"data:image/jpeg;base64,", title:"Last light on the water", cat:"Landscape", place:"Gokarna", exif:"ƒ/11 · 1/60s · ISO 100 · 70mm", ar:"1/1"},
  {src:"data:image/jpeg;base64,", title:"Quiet study", cat:"Portrait", place:"Hyderabad", exif:"ƒ/1.4 · 1/160s · ISO 800 · 85mm", ar:"1/1"},
  {src:"data:image/jpeg;base64,", title:"Window light", cat:"Portrait", place:"Studio", exif:"ƒ/1.8 · 1/100s · ISO 640 · 50mm", ar:"6/5"}
];

const $ = s => document.querySelector(s);
const pad = n => String(n).padStart(2,"0");

const nav = $("#nav");
const hero = $("#hero");
const onScroll = () => nav.classList.toggle("solid", scrollY > hero.offsetHeight - innerHeight - 10);
addEventListener("scroll", onScroll, {passive:true});
onScroll();

$("#burger").addEventListener("click", () => {
  const open = nav.classList.toggle("open");
  $("#burger").setAttribute("aria-expanded", open);
});
document.querySelectorAll("#links a").forEach(a => a.addEventListener("click", () => {
  nav.classList.remove("open");
  $("#burger").setAttribute("aria-expanded", false);
}));


const scene = $("#scene"), cam = $("#cam"), full = $("#full"), glow = $("#glow"), shade = $("#shade"), hint = $("#hint"), copyEl = document.querySelector(".hero-copy"), frameNo = $("#frameNo");
const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const easeBack = t => { const c = 1.9; return 1 + (c + 1) * Math.pow(t - 1, 3) + c * Math.pow(t - 1, 2); };
const easeOut = t => 1 - Math.pow(1 - t, 3);
const ORIGIN = {x: 790, y: 455};
const SPIN = [-28, 20, -16, 24, -22, 14, -18];
const photos = [...document.querySelectorAll(".layer.photo")].map((el, i) => {
  const s = el.style;
  const x = +s.getPropertyValue("--x"), y = +s.getPropertyValue("--y"), w = +s.getPropertyValue("--w");
  return {el, i, cx: x + w / 2, cy: y + (el.naturalHeight ? el.naturalHeight * w / el.naturalWidth : w * .9) / 2, w};
});
photos.forEach(p => p.el.decode?.().then(() => { p.cy = +p.el.style.getPropertyValue("--y") + p.el.naturalHeight / 2; render(); }).catch(() => {}));
const still = matchMedia("(prefers-reduced-motion: reduce)").matches;
if (still) hero.style.height = "100vh";

function render(){
  const r = hero.getBoundingClientRect();
  const span = hero.offsetHeight - innerHeight;
  const p = still ? 1 : clamp(-r.top / (span || 1));
  const k = scene.offsetWidth / 1672;
  const c0 = easeOut(clamp(p / .14));
  const kick = Math.max(0, 1 - Math.abs(p - .14) / .025);
  cam.style.transform = `scale(${1.2 - .2 * c0 - kick * .03})`;
  let shown = 0;
  photos.forEach(ph => {
    const t = clamp((p - (.15 + ph.i * .06)) / .24);
    const e = easeBack(t);
    const dx = (ORIGIN.x - ph.cx) * (1 - e) * k, dy = (ORIGIN.y - ph.cy) * (1 - e) * k;
    ph.el.style.opacity = clamp(t * 5).toFixed(3);
    ph.el.style.transform = `translate(${dx}px,${dy}px) scale(${.1 + .9 * e}) rotate(${SPIN[ph.i] * (1 - e)}deg)`;
    ph.el.style.zIndex = t < 1 ? 2 : 1;
    if (t > .5) shown++;
  });
  frameNo.textContent = pad(shown);
  const f = clamp((p - .64) / .2);
  full.style.opacity = f;
  glow.style.opacity = 1 - f * .7;
  hint.style.opacity = 1 - clamp(p / .07);
  const cp = clamp((p - .8) / .14);
  copyEl.style.setProperty("--cp", easeOut(cp));
  copyEl.style.opacity = cp;
  copyEl.classList.toggle("live", cp > .5);
  shade.style.opacity = cp;
}
let ticking = false;
addEventListener("scroll", () => { if (!ticking) { ticking = true; requestAnimationFrame(() => { render(); ticking = false; }); } }, {passive:true});
addEventListener("resize", render);
render();

const grid = $("#grid");
PHOTOS.forEach((p, i) => {
  const f = document.createElement("figure");
  f.className = "shot";
  f.tabIndex = 0;
  f.dataset.cat = p.cat;
  f.dataset.i = i;
  f.style.setProperty("--ar", p.ar);
  f.innerHTML = `<img src="${p.src}" alt="${p.title}, ${p.place}" loading="lazy"><figcaption><div><h3>${p.title}</h3><small>${p.exif}</small></div><span class="no">${p.cat.toUpperCase()} · ${pad(i+1)}</span></figcaption>`;
  f.addEventListener("click", () => openLb(i));
  f.addEventListener("keydown", e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); openLb(i); } });
  grid.appendChild(f);
});

const cats = ["All", ...new Set(PHOTOS.map(p => p.cat))];
const filters = $("#filters");
cats.forEach(c => {
  const b = document.createElement("button");
  b.className = "chip";
  b.type = "button";
  const n = c === "All" ? PHOTOS.length : PHOTOS.filter(p => p.cat === c).length;
  b.innerHTML = `${c}<sup>${pad(n)}</sup>`;
  b.setAttribute("aria-pressed", c === "All");
  b.addEventListener("click", () => {
    filters.querySelectorAll(".chip").forEach(x => x.setAttribute("aria-pressed", x === b));
    grid.querySelectorAll(".shot").forEach(s => s.hidden = !(c === "All" || s.dataset.cat === c));
  });
  filters.appendChild(b);
});

document.querySelectorAll(".cat-card").forEach(a => a.addEventListener("click", () => {
  const g = a.dataset.go;
  const chip = [...document.querySelectorAll("#filters .chip")].find(c => c.firstChild.textContent === g);
  if (chip) chip.click();
  const sel = document.getElementById("f-type") || document.querySelector("#contact select");
  if (!chip && sel) { const o = [...sel.options].find(o => o.text === g); if (o) sel.value = o.value || o.text; }
}));

const lb = $("#lb");
let cur = 0;
let lastFocus = null;
const visible = () => [...grid.querySelectorAll(".shot:not([hidden])")].map(s => +s.dataset.i);

function show(i){
  cur = i;
  const p = PHOTOS[i];
  const list = visible();
  $("#lb-img").src = p.src;
  $("#lb-img").alt = p.title;
  $("#lb-title").textContent = p.title;
  $("#lb-exif").textContent = `${p.place} · ${p.exif}`;
  $("#lb-count").textContent = `${pad(list.indexOf(i)+1)} / ${pad(list.length)}`;
}
function openLb(i){
  lastFocus = document.activeElement;
  show(i);
  lb.hidden = false;
  document.body.style.overflow = "hidden";
  $("#lb-close").focus();
}
function closeLb(){
  lb.hidden = true;
  document.body.style.overflow = "";
  lastFocus && lastFocus.focus();
}
function step(d){
  const list = visible();
  const k = (list.indexOf(cur) + d + list.length) % list.length;
  show(list[k]);
}
$("#lb-close").addEventListener("click", closeLb);
$("#lb-prev").addEventListener("click", () => step(-1));
$("#lb-next").addEventListener("click", () => step(1));
lb.addEventListener("click", e => { if (e.target === lb || e.target.classList.contains("lb-stage")) closeLb(); });
addEventListener("keydown", e => {
  if (lb.hidden) return;
  if (e.key === "Escape") closeLb();
  if (e.key === "ArrowRight") step(1);
  if (e.key === "ArrowLeft") step(-1);
});
let tx = 0;
lb.addEventListener("touchstart", e => tx = e.touches[0].clientX, {passive:true});
lb.addEventListener("touchend", e => { const d = e.changedTouches[0].clientX - tx; if (Math.abs(d) > 50) step(d < 0 ? 1 : -1); });

if ("IntersectionObserver" in window && !matchMedia("(prefers-reduced-motion: reduce)").matches) {
  const io = new IntersectionObserver(es => es.forEach(en => {
    if (en.isIntersecting) { en.target.classList.remove("pre"); io.unobserve(en.target); }
  }), {rootMargin:"0px 0px -8% 0px"});
  document.querySelectorAll(".reveal").forEach(el => {
    const r = el.getBoundingClientRect();
    if (r.top > innerHeight) { el.classList.add("pre"); io.observe(el); }
  });

  const cio = new IntersectionObserver(es => es.forEach(en => {
    if (!en.isIntersecting) return;
    const el = en.target, end = +el.dataset.count, t0 = performance.now();
    const tick = t => { const k = Math.min((t - t0) / 1400, 1); el.textContent = Math.round(end * (1 - Math.pow(1 - k, 3))); if (k < 1) requestAnimationFrame(tick); };
    requestAnimationFrame(tick);
    cio.unobserve(el);
  }), {threshold:.6});
  document.querySelectorAll("[data-count]").forEach(el => cio.observe(el));
}

document.querySelectorAll("[data-copy]").forEach(b => b.addEventListener("click", () => {
  const txt = b.dataset.copy;
  const done = () => { b.textContent = "Copied"; setTimeout(() => b.textContent = "Copy", 1600); };
  if (navigator.clipboard) navigator.clipboard.writeText(txt).then(done).catch(() => {});
}));

$("#form").addEventListener("submit", e => {
  e.preventDefault();
  const f = e.target.elements, note = $("#note");
  const name = f.name.value.trim(), email = f.email.value.trim(), msg = f.message.value.trim();
  if (!name || !email || !msg) { note.textContent = "Add your name, email and a short message so I can reply."; return; }
  if (!/^\S+@\S+\.\S+$/.test(email)) { note.textContent = "That email address looks incomplete. Check it and try again."; return; }
  const to = $("#mail").textContent.trim();
  const body = `Name: ${name}\nEmail: ${email}\nShoot: ${f.type.value}\nDate: ${f.date.value || "Flexible"}\n\n${msg}`;
  const link = document.createElement("a");
  link.href = `mailto:${to}?subject=${encodeURIComponent("Shoot enquiry: " + f.type.value)}&body=${encodeURIComponent(body)}`;
  link.click();
  note.textContent = `Your email app should open with the enquiry filled in. If it doesn't, write to ${to}.`;
});

$("#yr").textContent = new Date().getFullYear();
